optimization-iteration.patch:
diff --git a/tools/bot-evaluation/src/xml.rs b/tools/bot-evaluation/src/xml.rs
index 3accb4ad..eec14860 100644
--- a/tools/bot-evaluation/src/xml.rs
+++ b/tools/bot-evaluation/src/xml.rs
@@ -167,7 +167,10 @@ fn emit(writer: &mut Writer<Vec<u8>>, name: &str, value: &Value) -> Result<()> {
         writer.write_event(Event::Empty(start))?;
         return Ok(());
     }
-    writer.write_event(Event::Start(start))?;
+    if value.is_object() { writer.write_event(Event::Start(start))?; } else {
+        let bytes = writer.get_mut();
+        bytes.push(b'<'); bytes.extend_from_slice(name.as_bytes()); bytes.push(b'>');
+    }
     if let Value::Object(map) = value {
         for (k, v) in map {
             if is_attribute(k) {
